do $seed_postcondition$
declare
  abbreviation_digest text;
begin
  if (select count(*) from public.vocabulary_source_entries) <> 1600
     or (select count(*) from public.lexemes) <> 1638
     or (select count(*) from public.lexeme_relations) <> 716
     or (select count(*) from public.lexeme_tags) <> 1638
  then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if (select count(*) from public.learning_tasks)
     + (select count(*) from public.game_sessions)
     + (select count(*) from public.learning_evidence)
     + (select count(*) from public.student_lexeme_models)
     + (select count(*) from public.student_lexeme_skill_states)
     + (select count(*) from public.student_lexeme_weaknesses) <> 0 then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1
    from public.lexemes as lexemes
    where not exists (
      select 1
      from public.vocabulary_source_entries as source_entries
      where source_entries.id = lexemes.source_entry_id
    )
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1
    from public.lexeme_relations as relations
    where not exists (
      select 1 from public.lexemes as lexemes where lexemes.id = relations.from_lexeme_id
    )
       or not exists (
      select 1 from public.lexemes as lexemes where lexemes.id = relations.to_lexeme_id
    )
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1
    from public.lexeme_tags as tags
    where not exists (
      select 1 from public.lexemes as lexemes where lexemes.id = tags.lexeme_id
    )
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1
    from public.lexemes
    where abbreviation_of_lexeme_id is not null
      and not exists (
        select 1
        from public.lexemes as targets
        where targets.id = lexemes.abbreviation_of_lexeme_id
      )
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1 from public.vocabulary_source_entries
    where canonical_key = ''
       or source_word_raw = ''
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1 from public.lexemes
    where canonical_key = ''
       or lemma = ''
       or display = ''
       or role = ''
       or quality_status = ''
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if exists (
    select 1 from public.lexeme_relations
    where type = ''
       or provenance = ''
  ) then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  if (select count(*) from public.lexemes where abbreviation_of_lexeme_id is not null)
       <> 11
  then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;

  select encode(digest(coalesce((
    select string_agg(
      id::text || ':' || coalesce(abbreviation_of_lexeme_id::text, ''),
      ','
      order by id::text
    )
    from public.lexemes
  ), ''), 'sha256'), 'hex')
    into abbreviation_digest;
  if abbreviation_digest is distinct from '72fd91da72c313009a122acaf1282ca9fc24e74ac6a4c4730a39edae0e587a6d' then
    raise exception 'EMPTY_TARGET_SEED_POSTCONDITION_FAILED';
  end if;
end
$seed_postcondition$;

commit;
